def adversarial_augment(email_text):
    zero_width_chars = ['\u200b', '\u200c', '\u200d', '\u2060']
    augmented = ''
    for c in email_text:
        augmented += c
        if random.random() < 0.1:
            augmented += random.choice(zero_width_chars)
    return augmented

# Used in training loop to harden model against zero-width char evasion
